def _runtime(name: str, *, handler: str | None = None) -> WorkflowRuntimeKey:
    return WorkflowRuntimeKey(
        source_fingerprint="source",
        handler=handler or name,
        fixture="fixture",
        kind="cpu",
        mode=name,
    )


def test_executor_blocks_failed_dependency_transitively() -> None:
    operations = (
        WorkflowOperation(id="root", stage="root", runtime=_runtime("root")),
        WorkflowOperation(
            id="child",
            stage="child",
            runtime=_runtime("child"),
            dependencies=("root",),
        ),
        WorkflowOperation(
            id="grandchild",
            stage="grandchild",
            runtime=_runtime("grandchild"),
            dependencies=("child",),
        ),
        WorkflowOperation(
            id="independent", stage="independent", runtime=_runtime("independent")
        ),
    )
    called: list[str] = []

    def runner(session, _placement):
        operation_id = session.operations[0].id
        called.append(operation_id)
        if operation_id == "root":
            raise WorkflowOperationFailed(operation_id)
        return operation_id

    execution = execute_workflow(
        compile_workflow(operations),
        devices=[WorkflowDevice(host="local", gpu="0")],
        runner=runner,
    )

    assert set(called) == {"root", "independent"}
    assert execution.results["session_000"].failed_operation_id == "root"
    assert execution.blocked_by_failed_operations == {
        "session_001": ("root",),
        "session_002": ("root",),
    }


class _Fixture:
    def environment(self, _stage: str | None = None) -> dict[str, str]:
        return {"ART_MODEL_SUPPORT_FIXTURE_PATH": "/tmp/model"}


class _Prepared:
    def __init__(self, run_dir: Path, stages: tuple[str, ...] | None = None) -> None:
        stages = stages or (
            "hf_parity",
            "packing_invariance",
            "length_trainability",
        )
        self.report = ValidationReport(
            git={"commit": "test"},
            base_model="model",
            model_key="model",
            stages=[ValidationStageResult(name=stage) for stage in stages],
        )
        self.architecture = ArchitectureReport(
            base_model="model",
            model_key="model",
            handler_key="model",
            recommended_min_layers=1,
        )
        self.fixture = _Fixture()
        self.run_dir = run_dir
        self.output_json = None
        self.allow_unvalidated_arch = False
        self.include_sensitivity = None

    def record(self, result: ValidationStageResult) -> None:
        stage = next(stage for stage in self.report.stages if stage.name == result.name)
        stage.passed = result.passed
        stage.skipped = result.skipped
        stage.metrics = dict(result.metrics)
        stage.artifact_dir = result.artifact_dir

    def record_fixture_metric(self, _metrics: dict[str, object]) -> None:
        pass


class _Forkservers:
    def __init__(self, *, fail: str | None = "hf_parity", stop: bool = True) -> None:
        self.calls: list[tuple[str, ...]] = []
        self.fail = fail
        self.stop = stop

    def run(self, _host: str, *, request_json: Path, **_kwargs):
        request = WorkflowStageWorkerSession.model_validate_json(
            Path(request_json).read_text(encoding="utf-8")
        )
        stages = tuple(item.stage for item in request.items)
        self.calls.append(stages)
        for item in request.items:
            result = ValidationStageResult(name=item.stage, passed=True)
            if item.stage == self.fail:
                result = ValidationStageResult(
                    name=item.stage,
                    passed=False,
                    metrics={"error": "sentinel root failure"},
                )
            Path(item.output_json).write_text(
                result.model_dump_json(), encoding="utf-8"
            )
            if not result.passed and self.stop:
                break
        return {"returncode": 0, "child_wall_s": 0.01}

    def metrics(self, _host: str) -> dict[str, float]:
        return {}


def _run(prepared: _Prepared, forkservers: _Forkservers) -> ValidationReport:
    return workflow_scheduler.run_prepared_workflows(
        [cast(PreparedWorkflow, prepared)],
        forkservers=cast(WorkflowForkserverPool, forkservers),
    )[0]


def test_hidden_correctness_failure_fails_visible_owner(
    monkeypatch, tmp_path: Path
) -> None:
    reference = WorkflowOperation(
        id=f"model:{CORRECTNESS_REFERENCE_STAGE}",
        stage=CORRECTNESS_REFERENCE_STAGE,
        runtime=_runtime("reference", handler="model"),
    )
    visible = WorkflowOperation(
        id="model:correctness_sensitivity",
        stage="correctness_sensitivity",
        runtime=_runtime("variants", handler="model"),
        dependencies=(reference.id,),
    )
    plan = compile_workflow((reference, visible))
    prepared = _Prepared(tmp_path / "run", ("correctness_sensitivity",))
    forkservers = _Forkservers(fail=CORRECTNESS_REFERENCE_STAGE)
    monkeypatch.setattr(
        workflow_scheduler, "compile_prepared_workflows", lambda *_args, **_kwargs: plan
    )
    monkeypatch.setattr(
        workflow_scheduler,
        "_visible_devices",
        lambda: [WorkflowDevice(host="local", gpu="0")],
    )

    report = _run(prepared, forkservers)

    owner = report.stages[0]
    assert owner.name == "correctness_sensitivity"
    assert owner.passed is False and owner.skipped is False
    assert owner.metrics["blocked"] is True
    assert owner.metrics["workflow_failed_dependencies"] == [reference.id]
    assert report.passed is False

from __future__ import annotations

import torch

from art.preprocessing.pack import PackedTensors


@torch.no_grad()
def build_sft_trajectory_tensors_from_packed_tensors(
    packed_tensors: PackedTensors,
) -> list[dict[str, torch.Tensor]]:
    tokens = packed_tensors["tokens"]
    assistant_mask = packed_tensors["assistant_mask"]
    labels = torch.where(assistant_mask, tokens, torch.full_like(tokens, -100))
    attention_mask = torch.ones_like(tokens, dtype=torch.long)
    return [
        {
            "input_ids": tokens[index].detach().clone(),
            "attention_mask": attention_mask[index].detach().clone(),
            "labels": labels[index].detach().clone(),
        }
        for index in range(int(tokens.shape[0]))
    ]

from __future__ import annotations

from contextlib import contextmanager
from typing import Any, Iterator

import torch
from torch import Tensor

from .trace_uids import TRACE_ROW_TOKEN_UIDS_ATTR, TRACE_UID_SPAN_ATTR


class GdnTraceTokenUidHooks:
    def attach_token_uids(self, tensor: Tensor, token_uids: Tensor) -> Tensor:
        setattr(
            tensor,
            TRACE_ROW_TOKEN_UIDS_ATTR,
            token_uids.detach().to(device="cpu", dtype=torch.int64).reshape(-1),
        )
        setattr(tensor, TRACE_UID_SPAN_ATTR, None)
        return tensor

    def token_uids_from_tensor(self, tensor: Tensor) -> Tensor | None:
        token_uids = getattr(tensor, TRACE_ROW_TOKEN_UIDS_ATTR, None)
        if not isinstance(token_uids, Tensor):
            return None
        return token_uids.detach().to(device="cpu", dtype=torch.int64).reshape(-1)

    def set_module_token_uids(self, module: Any, token_uids: Tensor | None) -> None:
        if module is None or token_uids is None:
            return
        setattr(
            module,
            TRACE_ROW_TOKEN_UIDS_ATTR,
            token_uids.detach().to(device="cpu", dtype=torch.int64).reshape(-1),
        )
        if hasattr(module, TRACE_UID_SPAN_ATTR):
            delattr(module, TRACE_UID_SPAN_ATTR)

    @torch.compiler.disable
    def prepare_in_proj_token_uids(self, gdn: Any, hidden_states: Tensor) -> None:
        from art.megatron.gdn import operator as gdn_operator

        token_uids = self.token_uids_from_tensor(hidden_states)
        if token_uids is None:
            return
        projection = gdn_operator._gdn_input_projection(gdn)
        if projection is None:
            return
        output_uids = self.column_parallel_input_token_uids(
            token_uids,
            hidden_states,
            projection,
        )
        in_proj = getattr(gdn, "in_proj", None)
        self.set_module_token_uids(in_proj, output_uids)
        self.set_module_token_uids(projection, output_uids)
        self.set_module_token_uids(getattr(in_proj, "qkv_lora", None), output_uids)
        self.set_module_token_uids(getattr(in_proj, "z_lora", None), output_uids)

    @torch.compiler.disable
    def column_parallel_input_token_uids(
        self, token_uids: Tensor, hidden_states: Tensor, projection: Any
    ) -> Tensor:
        from art.megatron.gdn import operator as gdn_operator

        if not gdn_operator._uses_sequence_parallel(projection):
            return token_uids.to(dtype=torch.int64).reshape(-1)
        seq_len, batch_size, _hidden_size = hidden_states.shape
        expected = int(seq_len) * int(batch_size)
        if int(token_uids.numel()) != expected:
            return token_uids.to(dtype=torch.int64).reshape(-1)
        uid_tensor = (
            token_uids.to(device=hidden_states.device, dtype=torch.int64)
            .reshape(batch_size, seq_len)
            .transpose(0, 1)
            .contiguous()
            .unsqueeze(-1)
        )
        gathered = gdn_operator._column_parallel_input(uid_tensor, projection)
        return (
            gathered.squeeze(-1)
            .transpose(0, 1)
            .contiguous()
            .reshape(-1)
            .detach()
            .to(device="cpu", dtype=torch.int64)
        )

    def set_out_proj_lora_token_uids(self, gdn: Any, hidden_states: Tensor) -> None:
        token_uids = self.token_uids_from_tensor(hidden_states)
        if token_uids is None:
            return
        self.set_module_token_uids(
            getattr(getattr(gdn, "out_proj", None), "lora", None),
            token_uids,
        )

    def set_out_norm_token_uids(self, gdn: Any, token_uids: Tensor) -> None:
        from art.megatron.gdn import operator as gdn_operator

        self.set_module_token_uids(
            getattr(gdn, "out_norm", None),
            token_uids.repeat_interleave(gdn_operator._local_value_heads(gdn)),
        )

    def set_out_proj_token_uids(
        self,
        gdn: Any,
        hidden_states: Tensor,
        *,
        sequence_parallel_output: bool,
    ) -> None:
        from art.megatron.gdn import operator as gdn_operator

        token_uids = self.token_uids_from_tensor(hidden_states)
        if token_uids is None:
            return
        projection = gdn_operator._gdn_output_projection(gdn)
        output_uids = self.row_parallel_output_token_uids(
            token_uids,
            hidden_states,
            projection,
            sequence_parallel_output=sequence_parallel_output,
        )
        self.set_module_token_uids(gdn, output_uids)
        self.set_module_token_uids(getattr(gdn, "out_proj", None), output_uids)
        self.set_module_token_uids(projection, output_uids)

    def row_parallel_output_token_uids(
        self,
        token_uids: Tensor,
        hidden_states: Tensor,
        projection: Any | None,
        *,
        sequence_parallel_output: bool,
    ) -> Tensor:
        from art.megatron.gdn import operator as gdn_operator

        token_uids = token_uids.to(dtype=torch.int64).reshape(-1)
        if (
            projection is None
            or not gdn_operator._uses_sequence_parallel(projection)
            or not sequence_parallel_output
        ):
            return token_uids
        token_count = gdn_operator._hidden_token_count(hidden_states)
        if token_count <= 0:
            return token_uids.new_empty((0,))
        if int(token_uids.numel()) != token_count:
            return token_uids
        tp_size = gdn_operator._tp_world_size(projection)
        tp_rank = gdn_operator._tp_rank(projection)
        rows_per_rank, remainder = divmod(token_count, tp_size)
        if remainder != 0:
            return token_uids
        start = tp_rank * rows_per_rank
        return token_uids[start : start + rows_per_rank].contiguous()

    def pad_token_uids_for_stream(self, token_uids: Tensor, stream: Tensor) -> Tensor:
        from art.megatron.gdn import operator as gdn_operator

        token_count = gdn_operator._hidden_token_count(stream)
        if token_count == int(token_uids.numel()):
            return token_uids
        padded = token_uids.new_full((token_count,), -1)
        copied = min(token_count, int(token_uids.numel()))
        if copied:
            padded[:copied] = token_uids[:copied]
        return padded


@contextmanager
def install_gdn_trace_token_uid_hooks() -> Iterator[None]:
    from art.megatron.gdn import operator as gdn_operator

    previous = gdn_operator.set_gdn_trace_token_uid_hooks(GdnTraceTokenUidHooks())
    try:
        yield
    finally:
        gdn_operator.set_gdn_trace_token_uid_hooks(previous)

from __future__ import annotations

from typing import Any

import torch

TRACE_ROW_TOKEN_UIDS_ATTR = "_art_trace_row_token_uids"
TRACE_UID_SPAN_ATTR = "_art_trace_uid_span"


def extract_tensor_attr(value: Any, attr_name: str) -> Any:
    if isinstance(value, torch.Tensor):
        return getattr(value, attr_name, None)
    if isinstance(value, dict):
        for item in value.values():
            attr_value = extract_tensor_attr(item, attr_name)
            if attr_value is not None:
                return attr_value
    if isinstance(value, (list, tuple)):
        for item in value:
            attr_value = extract_tensor_attr(item, attr_name)
            if attr_value is not None:
                return attr_value
    return None


def normalize_row_token_uids(value: Any) -> torch.Tensor | None:
    if not isinstance(value, torch.Tensor):
        return None
    return value.detach().to(device="cpu", dtype=torch.int64).reshape(-1)


def positive_uid_span(value: Any) -> int | None:
    return int(value) if isinstance(value, int) and value > 0 else None


def row_token_uids_from_trace_sources(
    *,
    inputs: Any,
    output: Any,
    module: Any,
    row_count: int | None = None,
    prefer_uid_span: bool = False,
) -> tuple[torch.Tensor | None, int | None]:
    candidates = (
        (
            extract_tensor_attr(output, TRACE_ROW_TOKEN_UIDS_ATTR),
            extract_tensor_attr(output, TRACE_UID_SPAN_ATTR),
        ),
        (
            extract_tensor_attr(inputs, TRACE_ROW_TOKEN_UIDS_ATTR),
            extract_tensor_attr(inputs, TRACE_UID_SPAN_ATTR),
        ),
        (
            getattr(module, TRACE_ROW_TOKEN_UIDS_ATTR, None),
            getattr(module, TRACE_UID_SPAN_ATTR, None),
        ),
    )
    row_count_matches: list[tuple[torch.Tensor, int | None]] = []
    tensor_candidates: list[tuple[torch.Tensor, int | None]] = []
    for row_token_uids, uid_span in candidates:
        row_token_uids = normalize_row_token_uids(row_token_uids)
        if row_token_uids is None:
            continue
        candidate = (row_token_uids, positive_uid_span(uid_span))
        tensor_candidates.append(candidate)
        if row_count is None or int(row_token_uids.numel()) == int(row_count):
            row_count_matches.append(candidate)
    if not tensor_candidates:
        return None, None

    def _select(
        options: list[tuple[torch.Tensor, int | None]],
    ) -> tuple[torch.Tensor, int | None] | None:
        if prefer_uid_span:
            for row_token_uids, uid_span in options:
                if uid_span is not None:
                    return row_token_uids, uid_span
        return options[0] if options else None

    selected = _select(row_count_matches) or _select(tensor_candidates)
    return selected if selected is not None else (None, None)


def expand_token_uids_for_heads(
    token_uids: torch.Tensor,
    *,
    head_count: int,
) -> torch.Tensor:
    if token_uids.ndim != 1:
        raise RuntimeError(
            f"Expected 1D token UID tensor, got shape={tuple(token_uids.shape)}"
        )
    if head_count <= 0:
        raise RuntimeError(f"Expected positive head_count, got {head_count}")
    return token_uids.repeat_interleave(head_count).contiguous()

